import{_ as a,c as n,o as p,ag as o}from"./chunks/framework.DPDPlp3K.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/storefronts/多语言.md","filePath":"shopify/storefronts/多语言.md"}'),e={name:"shopify/storefronts/多语言.md"};function l(t,s,i,r,c,h){return p(),n("div",null,s[0]||(s[0]=[o(`<blockquote><p>首次进入仓库时间：2026-03-24</p></blockquote><h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Shopify 开发实战：Shopify 多语言配置 一篇讲清楚</li><li>手把手梳理 Shopify：Shopify 多语言配置 的关键用法和避坑点</li><li>做 Shopify 项目别只会改主题，这篇带你搞懂 Shopify 多语言配置</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合 Shopify 主题和应用开发者，围绕「Shopify 多语言配置」梳理核心概念、配置路径和实战注意点，方便项目中快速对照。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群，群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源，关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Shopify 项目最容易卡住的地方，往往不是“会不会写代码”，而是主题、应用和后台配置之间的关系没理顺。</strong></p><p>很多同学做 Shopify 开发时，会同时碰到 Liquid、主题目录、Checkout、Metafields、应用后台、性能优化这些概念。单独看不难，放到真实项目里就容易散。</p><p>这篇围绕「Shopify 多语言配置」把原始笔记整理成更适合阅读和复用的版本，适合做主题开发、应用开发或者接手 Shopify 项目时快速对照。</p><h2 id="shopify-实战整理" tabindex="-1">Shopify 实战整理 <a class="header-anchor" href="#shopify-实战整理" aria-label="Permalink to &quot;Shopify 实战整理&quot;">​</a></h2><p>下面进入 Shopify 相关内容整理。建议大家边看边对照自己的店铺、主题代码和应用后台，很多问题只有放到真实配置里才容易看清楚。</p><p>如果你正在做 Shopify 项目，可以重点留意主题代码、后台配置、应用能力和官方限制之间的边界，很多线上问题都出在这些交界处。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>Shopify 多语言 JSON 文件的工作原理：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>文件结构</span></span>
<span class="line"><span>项目里通常有几个 locale 文件：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>locales/en.default.json — 英文（默认语言）</span></span>
<span class="line"><span>locales/zh-CN.json — 中文（如果有的话）</span></span>
<span class="line"><span>其他语言...</span></span>
<span class="line"><span>如何使用</span></span>
<span class="line"><span>在 Liquid 模板里通过 | t filter 调用：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{{ &#39;products.product.from_lowest_price_html&#39; | t: lowest_price: money_price }}</span></span>
<span class="line"><span>这里的 key products.product.from_lowest_price_html 对应 JSON 文件里的嵌套路径：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  &quot;products&quot;: {</span></span>
<span class="line"><span>    &quot;product&quot;: {</span></span>
<span class="line"><span>      &quot;from_lowest_price_html&quot;: &quot;from {{ lowest_price }}&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>| t 就是 translate 的缩写，Shopify 会根据当前店铺语言去对应的 JSON 文件里取值。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>带变量的翻译</span></span>
<span class="line"><span>翻译值里可以嵌入变量（用 {{ }} 包裹），调用时用命名参数传入：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{{ &#39;general.pagination.next&#39; | t }}</span></span>
<span class="line"><span>{{- 结果: &quot;Next&quot; -}}</span></span>
<span class="line"><span>{{ &#39;products.product.from_lowest_price_html&#39; | t: lowest_price: &quot;$1,008.00&quot; }}</span></span>
<span class="line"><span>{{- 结果: &quot;from $1,008.00&quot; -}}</span></span>
<span class="line"><span>带 HTML 的翻译</span></span>
<span class="line"><span>key 名里带 _html 后缀的（如 from_lowest_price_html），翻译值可以包含 HTML 标签，Shopify 会直接输出原始 HTML 而不转义：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;from_lowest_price_html&quot;: &quot;from &lt;strong&gt;{{ lowest_price }}&lt;/strong&gt;&quot;</span></span>
<span class="line"><span>多语言切换</span></span>
<span class="line"><span>当店铺切换语言时，| t 自动去对应语言的 JSON 文件取值，找不到 key 时降级到 en.default.json。这就是为什么改硬编码文本要改 locale 文件而不是直接写死在 Liquid 里。</span></span></code></pre></div><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你现在做 Shopify 更常遇到的是主题开发、Checkout 定制、应用接入，还是性能优化？如果你在「Shopify 多语言配置」上踩过坑，也可以把场景留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Shopify、主题开发、独立站</p>`,26)]))}const d=a(e,[["render",l]]);export{f as __pageData,d as default};
